#!/usr/bin/env python3
# Build indexes based on the .html generated by cellranger

import sys, os, pathlib, html, datetime, csv

# redirect stdout/stderr into the Snakemake log
log = open(snakemake.log[0], "w")
sys.stdout = sys.stderr = log

# load the shared template
script_dir    = pathlib.Path(__file__).parent
template_path = script_dir / "base_template.html"
if not template_path.exists():
    sys.exit(f"ERROR: missing base_template.html in {script_dir}")
TEMPLATE = template_path.read_text()

# determine the “captures”.html via snakemake.input.captures --> captures.csv under the column capture
with open(snakemake.input.captures) as f:
    reader = csv.DictReader(f)
    capture_ids = [row["capture"] for row in reader]

# parent folder for both cell_types/ and summary/
# Use summary_index to determine the parent directory since it's always present
captures_dir = pathlib.Path(snakemake.output.summary_index).parent.parent

# Determine which indexes to build based on config
indexes_to_build = []

# Only include "cell_types" if annotate is true
if snakemake.output.cell_types_index:  # This will be empty list when false
    indexes_to_build.append(("cell_types", snakemake.output.cell_types_index))

# Always include "summary"
indexes_to_build.append(("summary", snakemake.output.summary_index))

for name, out_index in indexes_to_build:
    title = f"Cellranger {name}"
    # we no longer glob — we iterate over capture_ids
    items = []
    for cid in capture_ids:
        # each html is named {capture_id}.html in the same directory as the index
        href = f"{cid}.html"
        items.append(
            f'      <li data-name="{html.escape(cid.lower())}">'
            f'<a href="{html.escape(href)}">{html.escape(cid)}</a></li>'
        )
    items_html = "\n".join(items)

    # render
    page = TEMPLATE.format(
        logo_html="",
        page_title=html.escape(title),
        home_link="",  # no home icon
        items=items_html,
        timestamp=datetime.datetime.now().isoformat(timespec="seconds"),
        iframe_src=""  # or another default
    )

    out_path = pathlib.Path(out_index)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(page)
    print(f"Wrote {out_path} with {len(capture_ids)} entries")

log.close()
